from flask import Flask, request
app = Flask(__name__)

def api_version(version):
    def decorator(f):
        def wrapped(*args, **kwargs):
            if request.headers.get('Accept-Version') != version:
                return {'error': 'Unsupported version'}, 406
            return f(*args, **kwargs)
        return wrapped

def require_auth(f):
    def wrapped(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return {'error': 'Missing token'}, 401
        return f(*args, **kwargs)
    return f

@app.route('/v1/users')
@api_version('1.0')
@require_auth
def get_users_v1():
    return {'version': '1.0', 'users': []}

@app.route('/v2/users')
@api_version('2.0')
@require_auth
def get_users_v2():
    return {'version': '2.0', 'users': [], 'new_feature': True}

